import os
import random
import string
from typing import List

# Data type: filesystem path string
# We need to return bytes that will be used by FUZZ_PARAM_STR() for pszFlowPath.
# Valid inputs include empty string, relative paths, absolute paths (POSIX/Windows),
# paths with dots (., ..), underscores, spaces, multiple separators, and trailing separators.
# Keep <=4096 bytes total.

MAX_TOTAL = 4096

_POSIX_SEPS = "/"
_WIN_SEPS = "\\\\/"  # allow both backslash and slash

POSIX_ROOTS = ["/", "/tmp/", "/var/tmp/", "/home/user/", "/usr/local/", "/dev/shm/"]
WIN_ROOTS = [
    "C:/", "D:/", "C:/temp/", "C:/Users/Public/", "C:/Windows/Temp/", "\\\\?\\C:/"  # long path prefix
]

COMMON_SEGMENTS = [
    "md", "flow", "cache", "state", "logs", "ctpsim", "ctp", "mdapi",
    "session", "data", "persist", "run", "work", "tmp", ".hidden", "_meta",
]

EDGE_SEGMENTS = [
    ".", "..", " . ", ".. ", " .hidden", "..hidden", "aux", "prn", "nul",  # Windows reserved names
    "con", "com1", "lpt1", "NUL",
]

ALNUM = string.ascii_letters + string.digits
SAFE_EXTRA = ALNUM + "-_. "


def _rand(r: random.Random, n: int, alphabet: str) -> str:
    return "".join(r.choice(alphabet) for _ in range(n))


def _pick_root(r: random.Random, is_windows: bool) -> str:
    if is_windows:
        return r.choice(WIN_ROOTS)
    return r.choice(POSIX_ROOTS)


def _segment(r: random.Random, is_windows: bool) -> str:
    # Mix of common and random segments; avoid empty
    choice = r.random()
    if choice < 0.5:
        return r.choice(COMMON_SEGMENTS)
    if choice < 0.7:
        return r.choice(EDGE_SEGMENTS)
    # random printable safe name, avoid trailing dots/spaces on Windows
    seg = _rand(r, r.randint(1, 12), SAFE_EXTRA)
    if is_windows:
        seg = seg.rstrip(" .") or "x"
    return seg


def _join_seps(r: random.Random, is_windows: bool) -> str:
    if is_windows:
        # sometimes backslash, sometimes slash
        return r.choice(list(_WIN_SEPS))
    return "/"


def _build_path(r: random.Random) -> str:
    # Decide platform style
    style_pick = r.random()
    is_windows = style_pick < 0.5

    # Sometimes produce empty path to mean current directory
    if r.random() < 0.1:
        return ""

    # Relative vs absolute
    absolute = r.random() < 0.7

    parts: List[str] = []

    if absolute:
        root = _pick_root(r, is_windows)
        path = root
    else:
        path = ""
        # sometimes start with ./ or ../
        pre = r.random()
        if pre < 0.2:
            path = "./"
        elif pre < 0.35:
            path = "../"
        elif pre < 0.4 and is_windows:
            # Windows relative with .\\
            path = ".\\"

    # number of segments
    nseg = r.randint(0 if path else 1, 6)

    for i in range(nseg):
        seg = _segment(r, is_windows)
        # occasionally insert repeated separators
        if r.random() < 0.15:
            path += _join_seps(r, is_windows) * r.randint(2, 3)
        else:
            if i > 0 or path:
                path += _join_seps(r, is_windows)
        path += seg

    # Optionally add trailing separator
    if r.random() < 0.4:
        path += _join_seps(r, is_windows)

    # Normalize excessive length to keep within fuzzer's 128B truncation bias but varied
    max_len = r.choice([32, 64, 80, 120])
    if len(path) > max_len:
        path = path[:max_len]
        # avoid truncating in the middle of a multibyte (we use ASCII only) and avoid Windows trailing dot/space
        path = path.rstrip(" ")

    return path


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Sometimes try a small corpus of particularly interesting paths
    corpus = [
        "",  # empty => current directory
        ".", "..", "./", "../", "./.", "../..",
        "/", "/tmp/", "/tmp/md", "/var/tmp/ctpsim/flow/", "/home/user/.hidden_md/",
        "C:/", "C:/temp/mdapi/", "C:/Users/Public/ctp/md_flow/",
        "C:/Windows/Temp/ctpdata/", "\\\\?\\C:/very/long/prefix/",
        "md_flow", "./md_flow", "../md_flow",
        "md/flow/cache", "md//flow///state/",  # repeated separators
        "md .flow/with space/",
    ]

    if r.random() < 0.45:
        path = r.choice(corpus)
    else:
        path = _build_path(r)

    # Ensure ASCII bytes and null-terminated expectation by fuzzer consumer; FUZZ_PARAM_STR() likely uses std::string,
    # so we should not include embedded NUL. Keep printable range.
    path = path.replace("\x00", "_")

    data = path.encode('utf-8')

    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]

    return data

import random
import string
from typing import List

# This generator produces instrument identifier strings suitable for CTP/Thost MD API
# fuzzer stubs that call FUZZ_PARAM_STR to derive a base instrument ID and then
# construct multiple writable C-strings with suffixes. The stub caps base at 16 chars
# and then appends _<index>, truncating to 31 chars and ensuring NUL termination.
# We return a bytes buffer that FUZZ_PARAM_STR will read from. To encourage coverage,
# we randomly select realistic Chinese futures symbols, options, indices, and edge-ish
# but valid ASCII patterns, while keeping within the expected constraints.

REALISTIC_PREFIXES = [
    # Futures main month-like roots
    "IF", "IH", "IC",  # CSI index futures
    "CU", "AL", "ZN", "PB", "NI", "SN", "SS",  # Nonferrous
    "RB", "HC", "I", "J", "JM", "ZC", "FG", "SA", "MA", "TA", "RU", "BU", "NR",
    "AG", "AU",  # Precious metals
    "AP", "CF", "SR", "RM", "OI", "CY",  # Agri
    "SC",  # Crude oil
]

# Option underlyings and styles (still plain ASCII IDs)
OPTION_BASES = [
    "CUO", "AUO", "M", "C", "SR", "CF", "RUO", "IO", "MFO", "ETF",
]

# Some patterns to vary character classes while remaining valid ASCII
ALNUM_SETS = [
    string.ascii_uppercase,
    string.ascii_lowercase,
    string.digits,
    string.ascii_uppercase + string.digits,
    string.ascii_uppercase + string.digits + "_",
]

SUFFIX_MONTHS = ["01", "02", "03", "04", "05", "06", "07", "08", "09", "10", "11", "12"]


def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]


def _rand_alnum(rng: random.Random, min_len: int, max_len: int) -> str:
    charset = _rand_choice(rng, ALNUM_SETS)
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(charset) for _ in range(n))


def _mk_future_id(rng: random.Random) -> str:
    # e.g., RB2401, CU2312, IF2406
    root = _rand_choice(rng, REALISTIC_PREFIXES)
    # 2-digit year + 2-digit month or 3-digit month code
    if rng.random() < 0.8:
        year = rng.randint(20, 35)  # 2020-2035 style
        mon = _rand_choice(rng, SUFFIX_MONTHS)
        tail = f"{year:02d}{mon}"
    else:
        # Some exchanges use 3-digit delivery codes occasionally in user data
        tail = f"{rng.randint(1, 12):03d}"
    return root + tail


def _mk_option_id(rng: random.Random) -> str:
    # Simplified option symbol like M2405-P-2600 or CU2407-C-070000
    base = _rand_choice(rng, OPTION_BASES)
    year = rng.randint(20, 35)
    mon = _rand_choice(rng, SUFFIX_MONTHS)
    style = rng.choice(["C", "P"])
    strike = str(rng.choice([
        rng.randrange(100, 9999, 50),
        rng.randrange(1000, 30000, 100),
        rng.randrange(10, 999) * 10,
    ]))
    sep = rng.choice(["-", "_"])  # allow underscore which stub also uses
    return f"{base}{year:02d}{mon}{sep}{style}{sep}{strike}"


def _mk_index_like(rng: random.Random) -> str:
    # Index or ETF-like tickers
    choice = rng.randint(0, 2)
    if choice == 0:
        return rng.choice(["SH000300", "SZ399001", "SZ399006", "SH000016"])
    elif choice == 1:
        return rng.choice(["IF_MAIN", "CU_INDEX", "RB_INDEX"])  # underscore variant
    else:
        return "ETF" + _rand_alnum(rng, 2, 6)


def _mk_edge_valid(rng: random.Random) -> str:
    # Create a valid but edge-y base: max length 16, mix of cases, underscores
    parts = []
    while len("".join(parts)) < 12:
        parts.append(_rand_alnum(rng, 2, 5))
        if rng.random() < 0.6:
            parts.append("_")
    s = "".join(parts)
    # Trim to at most 16 for base; stub will trim anyway, but we keep valid
    return s[:16] if s else "I"


def _pick_base(rng: random.Random) -> str:
    r = rng.random()
    if r < 0.45:
        return _mk_future_id(rng)
    elif r < 0.70:
        return _mk_option_id(rng)
    elif r < 0.85:
        return _mk_index_like(rng)
    else:
        return _mk_edge_valid(rng)


def _ensure_constraints(base: str) -> str:
    # FUZZ_PARAM_STR is used directly and then possibly resized to 16.
    # We return ASCII, non-empty, and reasonably short (<= 31) so that with suffixes
    # the stub still has meaningful identifiers before truncation.
    if not base:
        base = "I"
    # Keep ASCII and remove spaces to be safe for CIDs
    base = base.encode("ascii", errors="ignore").decode("ascii")
    if not base:
        base = "I"
    if len(base) > 31:
        base = base[:31]
    return base


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    base = _pick_base(rng)
    base = _ensure_constraints(base)

    # Occasionally craft extremely short or single-char bases to test suffix handling
    if rng.random() < 0.1:
        base = rng.choice(["I", "U", "Q", "X"])  # aligns with stubs' defaults

    # Return as raw bytes; FUZZ_PARAM_STR will consume this as the base string buffer.
    # Ensure no embedded NUL so the entire base is visible.
    if "\x00" in base:
        base = base.replace("\x00", "_")

    # Append a newline sometimes to simulate input boundaries if parser tolerates it;
    # still valid since FUZZ framework typically reads raw bytes into string and may not
    # include newline; keep it minimal and ASCII.
    if rng.random() < 0.2 and len(base) < 30:
        base += "\n"

    data = base.encode("ascii", errors="ignore")
    # Cap size strictly below fuzz framework maximum (here far below 4096)
    if len(data) > 256:
        data = data[:256]
    return data
